from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        m = len(queries)

        if all(x == 0 for x in nums):
            return 0

        def check(k):
            for i in range(n):
                target = nums[i]
                if target == 0:
                    continue
                # Collect vals of first k queries that cover index i
                vals = []
                for j in range(k):
                    l, r, v = queries[j]
                    if l <= i <= r:
                        vals.append(v)
                if sum(vals) < target:
                    return False
                # Subset sum: can we reach exactly `target`?
                # Use bitmask for efficiency
                reachable = 1  # bit 0 set => sum 0 reachable
                mask = (1 << (target + 1)) - 1
                for v in vals:
                    reachable |= (reachable << v)
                    reachable &= mask
                    if (reachable >> target) & 1:
                        break
                if not ((reachable >> target) & 1):
                    return False
            return True

        lo, hi = 1, m
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if check(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
